public int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
  int bytesNeeded = 0;
  int ch = 0;
  int len = 0;
  int limit = bb.limit();

  for (; i < limit; i++) {
    byte b = bb.get(i);
    if ((b & 0x80) == 0) {
      len = 1;
      ch = b & 0x7F;
    } else if ((b & 0xE0) == 0xC0) {
      len = 2;
      ch = b & 0x1F;
    } else if ((b & 0xF0) == 0xE0) {
      len = 3;
      ch = b & 0x0F;
    } else if ((b & 0xF8) == 0xF0) {
      len = 4;
      ch = b & 0x07;
    } else {
      // Java only supports BMP, so we throw an exception if we find a character outside of that range.
      throw new IllegalArgumentException("Invalid UTF-8 sequence");
    }
    for (int j = 1; j < len; j++) {
      byte b2 = bb.get(i + j);
      if ((b2 & 0xC0) != 0x80) {
        // Not a continuation character.
        throw new IllegalArgumentException("Invalid UTF-8 sequence");
      }
      ch = (ch << 6) | (b2 & 0x3F);
    }
    i += len - 1;
    sb.append((char) ch);
  }
  return i;
}

